<script lang="ts">
 import {page} from '$app/stores';import {api,documents,message,notify} from '$lib/workspace';import {buildExperimentArchive,bundleDocuments,documentPaths} from '$lib/export.mjs';import Icon from '$lib/Icon.svelte';
 let selected=$page.url.searchParams.get('id')||'',history=false,busy=false,error='',progress='',complete=false,warnings:string[]=[];
 $: experiments=$documents.filter(d=>d.doc_type==='experiment');
 $: if(!selected&&experiments.length)selected=experiments[0].revision.document_id;
 $: parent=experiments.find(d=>d.revision.document_id===selected);
 $: included=parent?bundleDocuments(parent,$documents):[];
 $: paths=parent?documentPaths(parent,included):new Map();
 async function download(){if(!parent||busy)return;busy=true;error='';complete=false;try{
  progress='Loading your latest saved work…';
  const latest=await api.call<{drafts:typeof $documents}>('content_list',{mine:true});
  const latestParent=latest?.drafts.find(d=>d.revision.document_id===parent?.revision.document_id);
  if(!latestParent)throw new Error('This experiment is no longer available in your workspace.');
  const result=await buildExperimentArchive({parent:latestParent,documents:latest!.drafts,client:api,history,origin:location.origin,onProgress:(text:string)=>progress=text});
  const blob=new Blob([result.bytes as Uint8Array<ArrayBuffer>],{type:'application/zip'});const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=result.filename;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),60000);complete=true;warnings=result.warnings;notify('Your experiment folder is ready.');
 }catch(e){error=message(e);}finally{busy=false;progress='';}}
</script>
<div class="page-heading"><span class="eyebrow">YOUR WORK BELONGS WITH YOU</span><h1>Take it with you.</h1><p>Ordinary files. Meaningful connections. Yours to read, edit, and keep.</p></div><div class="export-layout"><section class="panel export-options"><span class="export-symbol"><Icon name="download" size={28}/></span><h2>Your experiment, in a folder.</h2><p>Download your saved notes and story as Markdown, together with their connections, work records, and local attachments.</p><label for="export-experiment">Choose an experiment<select id="export-experiment" bind:value={selected} disabled={busy}><option value="" disabled>Select an experiment</option>{#each experiments as experiment}<option value={experiment.revision.document_id}>{experiment.title}</option>{/each}</select></label><label class="checkbox-label"><input type="checkbox" bind:checked={history} disabled={busy}/><span>Include saved version history<small>Keep the earlier versions, too.</small></span></label><div class="privacy-note"><Icon name="lock" size={18}/><p>This is a private archive, including your personal notes. Sharing the folder shares its contents.</p></div>{#if error}<p class="alert" role="alert">{error}</p>{/if}<button class="button primary full" on:click={download} disabled={!parent||busy}><Icon name="download" size={17}/>{busy?'Preparing your folder…':'Download experiment folder'}</button>{#if progress}<p class="fine" role="status">{progress}</p>{/if}{#if complete}<p class="success" role="status">Your download is ready. Everything saved here stays in your workspace, too.</p>{/if}{#if complete&&warnings.length}<p class="fine warning">Some attachments point outside this site and remain links. The archive’s README lists them.</p>{/if}<p class="fine">Exports include saved versions. Save any open edits before downloading.</p></section><section class="folder-preview"><div class="row between"><span class="eyebrow">WHAT COMES WITH YOU</span><span class="fine">.zip → a folder of files</span></div><h3>{parent?.title||'Your experiment'}/</h3><div class="file-tree">{#each included as doc}<div><Icon name={doc.doc_type==='experiment'?'book':'leaf'} size={16}/><code>{paths.get(doc.revision.document_id)}</code></div>{/each}<div><Icon name="clock" size={16}/><code>work-log.md</code></div><div><Icon name="library" size={16}/><code>attachments/</code></div>{#if history}<div><Icon name="history" size={16}/><code>history/</code></div>{/if}<div><Icon name="book" size={16}/><code>README.md</code></div></div><div class="folder-foot"><h3>No app required.</h3><p>Open the files in a text editor, Obsidian, or whatever comes next. Permanent identities and links keep the connections useful.</p></div></section></div>
